void right_rotate(char str[],int n)
{
    char str1[101];
    int len=0;
    while(str[len]!='\0')
     {
         len++;
     }
    int i,j;
    for(i=0;i<len;++i)
     {
         if(i+n>=len)
          j=(i+n)%n;
         else
          j=i+n;
         str1[j]=str[i]; 
     }
    for(i=0;i<len;i++)
      str[i]=str1[i];
}

