#include <stdio.h>

int rotate(char str[], int n, int count)
{
    int i, j;
    for(i=0; i<=n; i++)
    {
        for(j=count; j>=0; j--)
        {
            str[j] = str[j-1];
        }
        str[0] = str[count];
        str[count]='\0';
    }
    return 0;
}

